"""File selection shared by the local lint and formatting commands."""

from pathlib import Path
import re
import subprocess


def repository_root() -> Path:
    return Path(subprocess.check_output(
        ["git", "rev-parse", "--show-toplevel"], text=True
    ).strip())


def git_files(root: Path, *args: str) -> list[str]:
    data = subprocess.check_output(["git", "-C", str(root), *args, "-z"])
    return [name.decode("utf-8", "surrogateescape") for name in data.split(b"\0") if name]


def generated(path: Path) -> bool:
    # Match the repository's DO NOT EDIT convention before the package clause,
    # including generators whose comments are not on the first three lines.
    header = path.read_bytes().split(b"\npackage ", 1)[0]
    return b"DO NOT EDIT" in header or bool(
        re.search(rb"(?im)^//.*(?:code generated|autogenerated)", header)
    )
